-- load_transaction_staging.sql
-- Generated by scripts/make_wwi_jobs.py: edit WWI_JOBS there and rerun it, rather than editing this file.
-- Fills WideWorldImportersDW.Integration.Transaction_Staging the way Microsoft's SSIS package would,
-- so Integration.MigrateStagedTransactionData has input to work on.
-- Run against WideWorldImportersDW. Needs the WideWorldImporters (shop) database on the same server.

SET NOCOUNT ON;

-- 1. Pick a time window: @WindowMonths long, ending @MonthsBack months before the warehouse's last load.
--    The default is the dev batch; jobs/transaction.json changes it for the holdout.
DECLARE @MonthsBack   int = 0;
DECLARE @WindowMonths int = 1;
DECLARE @LastLoad   datetime2(7) = (SELECT [Cutoff Time] FROM Integration.[ETL Cutoff] WHERE [Table Name] = N'Transaction');
DECLARE @NewCutoff  datetime2(7) = DATEADD(month, -@MonthsBack, @LastLoad);
DECLARE @LastCutoff datetime2(7) = DATEADD(month, -@WindowMonths, @NewCutoff);

-- 2. Clear staging (in-memory tables don't allow TRUNCATE)
DELETE FROM Integration.Transaction_Staging;

-- 3. Pull the rows from the shop database. In-memory tables can't be written in the same
--    statement as another user database, so go through a temp table.
CREATE TABLE #rows (
    [Date Key] date,
    [WWI Customer Transaction ID] int,
    [WWI Supplier Transaction ID] int,
    [WWI Invoice ID] int,
    [WWI Purchase Order ID] int,
    [Supplier Invoice Number] nvarchar(20),
    [Total Excluding Tax] decimal(18,2),
    [Tax Amount] decimal(18,2),
    [Total Including Tax] decimal(18,2),
    [Outstanding Balance] decimal(18,2),
    [Is Finalized] bit,
    [WWI Customer ID] int,
    [WWI Bill To Customer ID] int,
    [WWI Supplier ID] int,
    [WWI Transaction Type ID] int,
    [WWI Payment Method ID] int,
    [Last Modified When] datetime2(7)
);

INSERT INTO #rows
EXEC WideWorldImporters.Integration.GetTransactionUpdates @LastCutoff = @LastCutoff, @NewCutoff = @NewCutoff;

INSERT INTO Integration.Transaction_Staging ([Date Key], [WWI Customer Transaction ID], [WWI Supplier Transaction ID], [WWI Invoice ID], [WWI Purchase Order ID], [Supplier Invoice Number], [Total Excluding Tax], [Tax Amount], [Total Including Tax], [Outstanding Balance], [Is Finalized], [WWI Customer ID], [WWI Bill To Customer ID], [WWI Supplier ID], [WWI Transaction Type ID], [WWI Payment Method ID], [Last Modified When])
SELECT [Date Key], [WWI Customer Transaction ID], [WWI Supplier Transaction ID], [WWI Invoice ID], [WWI Purchase Order ID], [Supplier Invoice Number], [Total Excluding Tax], [Tax Amount], [Total Including Tax], [Outstanding Balance], [Is Finalized], [WWI Customer ID], [WWI Bill To Customer ID], [WWI Supplier ID], [WWI Transaction Type ID], [WWI Payment Method ID], [Last Modified When]
FROM #rows;

DROP TABLE #rows;

-- 4. Open a lineage record. MigrateStagedTransactionData looks for one with no completion time.
EXEC Integration.GetLineageKey @TableName = N'Transaction', @NewCutoffTime = @NewCutoff;

-- 5. Report what got staged
SELECT COUNT(*) AS staged_rows, @LastCutoff AS window_from, @NewCutoff AS window_to
FROM Integration.Transaction_Staging;
